package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

var searchTemplate = template.Must(template.New("search").Parse(`
<html><body>
<h1>Product Search</h1>
<form method="POST" action="/search">
  <input name="q" value="{{.Query}}" size="40">
  <select name="category">
    <option value="all">All</option>
    <option value="electronics">Electronics</option>
    <option value="books">Books</option>
  </select>
  <button type="submit">Search</button>
</form>
<table border="1">
<tr><th>Name</th><th>Price</th><th>Category</th></tr>
{{range .Results}}
<tr><td>{{.Name}}</td><td>{{.Price}}</td><td>{{.Category}}</td></tr>
{{end}}
</table>
</body></html>
`))

type Product struct {
	Name     string
	Price    string
	Category string
}

type SearchPage struct {
	Query   string
	Results []Product
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "POST" {
		searchTemplate.Execute(w, SearchPage{})
		return
	}

	query := r.FormValue("q")
	category := r.FormValue("category")

	// Validate category against whitelist
	validCategories := map[string]bool{"all": true, "electronics": true, "books": true}
	if !validCategories[category] {
		category = "all"
	}

	var sqlQuery string
	if category == "all" {
		sqlQuery = fmt.Sprintf("SELECT name, price, category FROM products WHERE name ILIKE '%%%s%%'", query)
	} else {
		sqlQuery = fmt.Sprintf("SELECT name, price, category FROM products WHERE name ILIKE '%%%s%%' AND category = '%s'", query, category)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		results = append(results, p)
	}

	searchTemplate.Execute(w, SearchPage{Query: query, Results: results})
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app@localhost:5432/products?sslmode=disable"
	}

	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	// Connection pool settings
	db.SetMaxOpenConns(10)
	db.SetMaxIdleConns(5)

	// Restrict search length at application level
	http.HandleFunc("/search", func(w http.ResponseWriter, r *http.Request) {
		if r.Method == "POST" {
			q := r.FormValue("q")
			if len(q) > 100 {
				http.Error(w, "Query too long", http.StatusBadRequest)
				return
			}
			// Basic sanitization - remove obvious comment sequences
			q = strings.ReplaceAll(q, "/*", "")
			q = strings.ReplaceAll(q, "*/", "")
		}
		searchHandler(w, r)
	})
	http.HandleFunc("/health", healthHandler)

	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
